26	const PROCESSING_FEE = 5;
27	const INITIAL_ASSESSMENT_SURCHARGE_RATE = 0.1;
28	const LOYALTY_YEARS = 2;
29	const LOYALTY_DISCOUNT_RATE = 0.2;
30	
31	const BASE_PREMIUMS: Record<string, number | undefined> = {
32	  sword: 100,
33	  amulet: 60,
34	  staff: 80,
35	  potion: 40,
36	  rune: 25,
37	  moonstone: 25,
38	};
39	
40	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
41	
42	const CURSE_SURCHARGE_RATE = 0.5;
43	const HIGH_ENCHANTMENT_LEVEL = 5;
44	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
45	
46	const isCursed = (item: Item): boolean => item.cursed === true;
47	const isHighlyEnchanted = (item: Item): boolean =>
48	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
49	
50	/** Item-specific modifiers apply to the base premium of the affected item only. */
51	const itemSurchargesOf = (item: Item): number => {
52	  const basePremium = basePremiumOf(item);
53	  const curseSurcharge = isCursed(item) ? basePremium * CURSE_SURCHARGE_RATE : 0;
54	  const highEnchantmentSurcharge = isHighlyEnchanted(item)
55	    ? basePremium * HIGH_ENCHANTMENT_SURCHARGE_RATE
56	    : 0;
57	  return curseSurcharge + highEnchantmentSurcharge;
58	};
59	
60	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
61	const COMPONENT_BLOCK_SIZE = 3;
62	const COMPONENT_BLOCK_PREMIUM = 60;
63	
64	const isComponent = (type: string): boolean => COMPONENT_TYPES.has(type);
65	
66	const countByType = (items: Item[]): Map<string, number> => {
67	  const counts = new Map<string, number>();
68	  for (const item of items) {
69	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
70	  }
71	  return counts;
72	};
73	
74	/**
75	 * Items of one type are normally priced individually. The exception is
76	 * components: exactly 3 alike ones form a "building block" priced as a unit.
77	 */
78	const typeGroupPremium = (type: string, count: number): number =>
79	  isComponent(type) && count === COMPONENT_BLOCK_SIZE
80	    ? COMPONENT_BLOCK_PREMIUM
81	    : count * basePremiumOf({ type });
82	
83	const policyBasePremiumOf = (step: QuoteStep): number =>
84	  [...countByType(step.items)].reduce(
85	    (sum, [type, count]) => sum + typeGroupPremium(type, count),
86	    0,
87	  );
88	
89	const isLongStanding = (customer: Customer): boolean =>
90	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
91	
92	/** Kept as an exact fraction — only the final premium is rounded. */
93	const premiumBeforeRounding = (step: QuoteStep, customer: Customer): number => {
94	  const policyBasePremium = policyBasePremiumOf(step);
95	  const itemSurcharges = step.items.reduce((sum, item) => sum + itemSurchargesOf(item), 0);
96	  const initialAssessmentSurcharge = policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
97	  const loyaltyDiscount = isLongStanding(customer) ? policyBasePremium * LOYALTY_DISCOUNT_RATE : 0;
98	  return (
99	    policyBasePremium + itemSurcharges + initialAssessmentSurcharge - loyaltyDiscount + PROCESSING_FEE
100	  );
101	};
102	
103	/** Rounded up, in the MHPCO's favour. */
104	const finalPremiumFor = (step: QuoteStep, customer: Customer): number =>
105	  Math.ceil(premiumBeforeRounding(step, customer));
106	
107	export const runScenario = (scenario: Scenario): ScenarioOutput => ({
108	  results: scenario.steps.map((step) => ({ premium: finalPremiumFor(step, scenario.customer) })),
109	});
