const premiumBeforeRounding = (step: QuoteStep, customer: Customer): number => {
  const policyBasePremium = policyBasePremiumOf(step);
  const itemSurcharges = step.items.reduce((sum, item) => sum + itemSurchargesOf(item), 0);
